MatchVerifier — example implementation
class MatchVerifier(BaseAgent):
    def get_instructions(self) -&gt; str:
        return """You are an agent specialised in verifying
                  the validity of a match between a label
                  and a code in a Neo4j nomenclature graph."""

    def build_prompt(self, input: MatchVerificationInput) -&gt; str:
        return f"""Verify whether the code matches the activity.
        Activity: {input.activity}
        Proposed code: {input.code}
        Explanation: {input.proposed_explanation}
        Respond with: validity (bool), confidence (0-1), explanation."""
